1	// Pins what add() in app/app.js makes, so a backup the app itself made always imports again (Khoa's review of commit B:
2	// isValidTodo rejects whitespace-only titles and non-string ids). app.js is a plain page script with no exports, so it
3	// runs unchanged in a vm context with a minimal fake page. Run: node --test
4	const test = require('node:test');
5	const assert = require('node:assert/strict');
6	const fs = require('node:fs');
7	const path = require('node:path');
8	const vm = require('node:vm');
9	const crypto = require('node:crypto');
10	const backup = require('../app/backup.js');
11	
12	const appJs = fs.readFileSync(path.join(__dirname, '..', 'app', 'app.js'), 'utf8');
13	
14	function fakeElement() {
15	  const el = {
16	    textContent: '', innerHTML: '', hidden: false, value: '', className: '', dataset: {},
17	    append() {},
18	    querySelector(sel) { return (el.children[sel] ||= fakeElement()); },
19	    children: {},
20	  };
21	  return el;
22	}
23	
24	// Loads app.js on a readable list (empty unless given) and returns the add form plus every list the app tried to save.
25	function loadApp(initial = []) {
26	  const elements = {};
27	  const saved = [];
28	  const replaced = [];
29	  const store = {
30	    readError: false,
31	    load() { return { todos: initial, readError: false }; },
32	    save(todos) { saved.push(todos.map((t) => ({ ...t }))); return 'saved'; },
33	    replace(todos) { replaced.push(todos); return 'saved'; },
34	  };
35	  const document = {
36	    querySelector(sel) { return (elements[sel] ||= fakeElement()); },
37	    querySelectorAll() { return []; },
38	    createElement() { return fakeElement(); },
39	  };
40	  vm.runInNewContext(appJs, { ...backup, store, document, crypto });
41	  const submit = (value) => {
42	    document.querySelector('#title').value = value;
43	    document.querySelector('#add').onsubmit({ preventDefault() {} });
44	  };
45	  // The confirm dialog records each question and answers "Huỷ".
46	  const asked = [];
47	  Object.assign(document.querySelector('#confirm'), {
48	    showModal() { asked.push(document.querySelector('#confirm-text').textContent); },
49	    addEventListener(type, fn) { queueMicrotask(fn); },
50	  });
51	  const pick = (file) => document.querySelector('#import').onchange({ target: { files: [file], value: '' } });
52	  const count = () => document.querySelector('#count').textContent;
53	  // Clicks a filter tab: 'all', 'open' or 'done'.
54	  const filterBy = (f) => document.querySelector('#filters').onclick({ target: { dataset: { filter: f } } });
55	  const emptyShown = () => !document.querySelector('#empty').hidden;
56	  return { submit, saved, replaced, asked, pick, count, filterBy, emptyShown };
57	}
58	
59	// A file whose text() resolves only when the test says so.
60	function slowFile(text) {
61	  let finish;
62	  const done = new Promise((resolve) => { finish = resolve; });
63	  return { file: { size: text.length, text: () => done.then(() => text) }, finish };
64	}
65	
66	function backupOf(...titles) {
67	  return backup.toBackupText(titles.map((title, i) => ({ id: `id-${title}-${i}`, title, done: false, createdAt: 1 })));
68	}
69	
70	test('add form: trims the title and makes a string id', () => {
71	  const { submit, saved } = loadApp();
72	  submit('  Mua sữa  ');
73	  assert.equal(saved.length, 1);
74	  const [t] = saved[0];
75	  assert.equal(t.title, 'Mua sữa');
76	  assert.equal(typeof t.id, 'string');
77	  assert.notEqual(t.id, '');
78	  assert.equal(t.done, false);
79	  assert.equal(typeof t.createdAt, 'number');
80	});
81	
82	test('add form: skips a whitespace-only title', () => {
83	  const { submit, saved } = loadApp();
84	  submit('   ');
85	  submit('\t\n');
86	  assert.equal(saved.length, 0);
87	});
88	
89	test('open-todo count line: a dot every three digits from 1,000 up, like every other sentence (Linh, R9)', () => {
90	  const todos = (n, done = false) =>
91	    Array.from({ length: n }, (_, i) => ({ id: `id-${done}-${i}`, title: `Việc ${i}`, done, createdAt: 1 }));
92	  const { submit, count } = loadApp([...todos(999), ...todos(5, true)]);
93	  assert.equal(count(), '999 việc chưa xong');
94	  submit('Việc thứ 1000');
95	  assert.equal(count(), '1.000 việc chưa xong');
96	  assert.equal(loadApp(todos(12)).count(), '12 việc chưa xong');
97	  assert.equal(loadApp(todos(2001)).count(), '2.001 việc chưa xong');
98	  assert.equal(loadApp(todos(12500)).count(), '12.500 việc chưa xong');
99	});
100	
101	test('open-todo count line counts the whole list, whatever the filter (T-013)', () => {
102	  const todo = (i, done) => ({ id: `id-${i}`, title: `Việc ${i}`, done, createdAt: 1 });
103	  const { count, filterBy } = loadApp([todo(1, false), todo(2, false), todo(3, false), todo(4, true), todo(5, true)]);
104	  assert.equal(count(), '3 việc chưa xong');
105	  filterBy('done');
106	  assert.equal(count(), '3 việc chưa xong', 'tab "Đã xong"');
107	  filterBy('open');
108	  assert.equal(count(), '3 việc chưa xong', 'tab "Chưa xong"');
109	  filterBy('all');
110	  assert.equal(count(), '3 việc chưa xong', 'back to tab "Tất cả"');
111	});
112	
113	test('empty-list message only when the whole list is empty, not when a filter hides everything (T-014)', () => {
114	  const todo = (i, done) => ({ id: `id-${i}`, title: `Việc ${i}`, done, createdAt: 1 });
115	  const { emptyShown, filterBy } = loadApp([todo(1, false), todo(2, false), todo(3, false), todo(4, false)]);
116	  assert.equal(emptyShown(), false);
117	  filterBy('done');
118	  assert.equal(emptyShown(), false, 'tab "Đã xong" with no done todos');
119	  const allDone = loadApp([todo(1, true)]);
120	  allDone.filterBy('open');
121	  assert.equal(allDone.emptyShown(), false, 'tab "Chưa xong" with no open todos');
122	  assert.equal(loadApp([]).emptyShown(), true, 'a really empty list still shows it');
123	});
124	
125	test('a backup of todos the app made imports again', () => {
126	  const { submit, saved } = loadApp();
127	  for (const v of ['Mua sữa', '  Gọi mẹ ', '   ', 'Nộp thuế']) submit(v);
128	  const todos = saved.at(-1);
129	  assert.equal(todos.length, 3);
130	  const parsed = backup.parseBackup(backup.toBackupText(todos));
131	  assert.equal(parsed.ok, true, parsed.message);
132	  assert.deepEqual(parsed.todos, todos);
133	});
134	
135	test('two overlapping imports: the later-finishing one asks before replacing the list the first one filled', async () => {
136	  const { replaced, asked, pick } = loadApp();
137	  const large = slowFile(backupOf('Lớn 1', 'Lớn 2', 'Lớn 3'));
138	  const small = slowFile(backupOf('Nhỏ'));
139	  const first = pick(large.file);
140	  const second = pick(small.file);
141	  small.finish();
142	  await second;
143	  assert.equal(replaced.length, 1, 'the small file fills the empty list without asking');
144	  assert.deepEqual(asked, []);
145	  large.finish();
146	  await first;
147	  assert.deepEqual(asked, [backup.fill(backup.MESSAGES.confirmReplace, { n: 1, m: 3 })]);
148	  assert.equal(replaced.length, 1, 'cancelled, so the list from the small file stays');
149	});
