// A todo has: id, title, done, createdAt. No due date, no tags, no owner.
// Saving and importing decisions live in backup.js (persist, importBackup); this file only wires them to the page.
let todos = store.load().todos;
let filter = 'all';

const $ = (sel) => document.querySelector(sel);

function add(title) {
  todos.push({ id: crypto.randomUUID(), title: title.trim(), done: false, createdAt: Date.now() });
  commit();
}

function toggle(id) {
  const t = todos.find((x) => x.id === id);
  if (t) t.done = !t.done;
  commit();
}

function rename(id, title) {
  const t = todos.find((x) => x.id === id);
  if (!t || !confirm('Đổi tên việc này?')) return render();
  t.title = title.trim();
  // A failed save keeps its own message; after a read error ('skipped') the banner already says nothing is saved.
  if (commit().message || store.readError) return;
  show(`Đã đổi tên thành “${t.title}”.`);
}

function remove(id) {
  todos = todos.filter((x) => x.id !== id);
  commit();
}

function commit() {
  const result = persist(store, todos);
  show(result.message);
  render();
  return result;
}

function show(message) {
  $('#message').textContent = message || '';
}

function visible() {
  if (filter === 'open') return todos.filter((t) => !t.done);
  if (filter === 'done') return todos.filter((t) => t.done);
  return todos;
}

function render() {
  const list = $('#list');
  list.innerHTML = '';
  for (const t of visible()) {
    const li = document.createElement('li');
    li.className = t.done ? 'done' : '';
    li.innerHTML = `<label><input type="checkbox" ${t.done ? 'checked' : ''}> <span></span></label><button aria-label="Xoá">×</button>`;
    const span = li.querySelector('span');
    span.textContent = t.title;
    span.title = 'Nhấp đúp để đổi tên';
    span.ondblclick = () => {
      const input = document.createElement('input');
      input.value = t.title;
      input.setAttribute('aria-label', `Tên mới của việc ${t.title}`);
      span.replaceWith(input);
      input.focus();
      input.onkeydown = (e) => {
        if (e.key === 'Enter' && input.value.trim()) rename(t.id, input.value);
        if (e.key === 'Escape') render();
      };
    };
    li.querySelector('input').onchange = () => toggle(t.id);
    li.querySelector('button').onclick = () => remove(t.id);
    list.append(li);
  }
  const open = todos.filter((t) => !t.done).length;
  $('#count').textContent = `${formatCount(open)} việc chưa xong`;
  $('#unreadable').hidden = !store.readError;
  // Based on the whole list, not the filter; and not shown on a read error, where the list only looks empty.
  $('#empty').hidden = todos.length > 0 || store.readError;
}

// Resolves true only when the customer picks "Thay"; Esc and "Huỷ" resolve false.
function ask(question) {
  const dialog = $('#confirm');
  $('#confirm-text').textContent = question;
  dialog.returnValue = '';
  dialog.showModal();
  return new Promise((resolve) => {
    dialog.addEventListener('close', () => resolve(dialog.returnValue === 'yes'), { once: true });
  });
}

$('#add').onsubmit = (e) => {
  e.preventDefault();
  const input = $('#title');
  if (input.value.trim()) add(input.value);
  input.value = '';
};

$('#filters').onclick = (e) => {
  const f = e.target.dataset.filter;
  if (!f) return;
  filter = f;
  document.querySelectorAll('#filters button').forEach((b) => b.classList.toggle('on', b.dataset.filter === f));
  render();
};

$('#export').onclick = () => {
  if (todos.length === 0) return show(MESSAGES.nothingToBackUp);
  const text = toBackupText(todos);
  const url = URL.createObjectURL(new Blob([text], { type: 'application/json' }));
  const a = document.createElement('a');
  a.href = url;
  a.download = backupFileName(new Date());
  document.body.append(a);
  a.click();
  a.remove();
  // Revoking right after click() can break the download on Safari iOS, so wait.
  setTimeout(() => URL.revokeObjectURL(url), 10000);
  show(tooBigToImport(text) ? MESSAGES.backupTooBig : fill(MESSAGES.backedUp, { n: todos.length }));
};

$('#import').onchange = async (e) => {
  const input = e.target;
  const file = input.files[0];
  input.value = ''; // so the same file can be picked again
  if (!file) return;
  show(MESSAGES.reading);
  // Counted when importBackup decides whether to ask (after the file is read), not now: another import, an add or a
  // delete may change the list while the file is being read. importBackup only reads current.length and returns
  // current itself when nothing was replaced.
  const current = { get length() { return todos.length; } };
  const result = await importBackup({ store, current, file, ask });
  if (result.todos !== current) todos = result.todos;
  show(result.message);
  render();
};

$('#unreadable').textContent = MESSAGES.unreadable;
$('#empty').textContent = MESSAGES.emptyList;
render();

// Pins what add() in app/app.js makes, so a backup the app itself made always imports again (Khoa's review of commit B:
// isValidTodo rejects whitespace-only titles and non-string ids). app.js is a plain page script with no exports, so it
// runs unchanged in a vm context with a minimal fake page. Run: node --test
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');
const crypto = require('node:crypto');
const backup = require('../app/backup.js');

const appJs = fs.readFileSync(path.join(__dirname, '..', 'app', 'app.js'), 'utf8');

// Setting innerHTML or textContent drops what was appended, as in a real page; `appended` is what is left.
function fakeElement() {
  let html = '';
  let text = '';
  const el = {
    hidden: false, value: '', className: '', dataset: {}, attributes: {}, appended: [],
    get innerHTML() { return html; },
    set innerHTML(v) { html = v; el.appended = []; },
    get textContent() { return text; },
    set textContent(v) { text = v; el.appended = []; },
    append(...nodes) { el.appended.push(...nodes); },
    setAttribute(name, value) { el.attributes[name] = value; },
    replaceWith(node) { el.replacedWith = node; },
    remove() { el.removed = true; },
    focus() {},
    querySelector(sel) { return (el.children[sel] ||= fakeElement()); },
    children: {},
  };
  return el;
}

// Loads app.js on a readable list (empty unless given) and returns the add form plus every list the app tried to save.
// `saveResult` is what store.save answers ('saved', 'failed', or 'skipped' with `readError`).
function loadApp(initial = [], { saveResult = 'saved', readError = false } = {}) {
  const elements = {};
  const saved = [];
  const replaced = [];
  const store = {
    readError,
    load() { return { todos: initial, readError }; },
    save(todos) { saved.push(todos.map((t) => ({ ...t }))); return saveResult; },
    replace(todos) { replaced.push(todos); return 'saved'; },
  };
  const document = {
    querySelector(sel) { return (elements[sel] ||= fakeElement()); },
    querySelectorAll() { return []; },
    createElement() { return fakeElement(); },
  };
  // Native confirm() is recorded and answered "OK"; timers are recorded and fired by the test.
  const confirms = [];
  const timers = [];
  const confirm = (q) => { confirms.push(q); return true; };
  const setTimeout = (fn, ms) => timers.push({ fn, ms });
  const clearTimeout = (id) => { if (timers[id - 1]) timers[id - 1].fn = () => {}; };
  vm.runInNewContext(appJs, { ...backup, store, document, crypto, confirm, setTimeout, clearTimeout });
  const submit = (value) => {
    document.querySelector('#title').value = value;
    document.querySelector('#add').onsubmit({ preventDefault() {} });
  };
  // The confirm dialog records each question and answers "Huỷ".
  const asked = [];
  Object.assign(document.querySelector('#confirm'), {
    showModal() { asked.push(document.querySelector('#confirm-text').textContent); },
    addEventListener(type, fn) { queueMicrotask(fn); },
  });
  const pick = (file) => document.querySelector('#import').onchange({ target: { files: [file], value: '' } });
  const count = () => document.querySelector('#count').textContent;
  // Clicks a filter tab: 'all', 'open' or 'done'.
  const filterBy = (f) => document.querySelector('#filters').onclick({ target: { dataset: { filter: f } } });
  const emptyShown = () => !document.querySelector('#empty').hidden;
  // Rows on screen; renaming opens the edit box on row `row` (double-click, or a key such as 'Enter') and presses Enter.
  const rows = () => document.querySelector('#list').appended;
  const titleOf = (row) => rows()[row].querySelector('span');
  const startRename = (row, key) => {
    const span = titleOf(row);
    if (key) span.onkeydown({ key, preventDefault() {} });
    else span.ondblclick();
    return span.replacedWith;
  };
  const rename = (row, value, key) => {
    const input = startRename(row, key);
    input.value = value;
    input.onkeydown({ key: 'Enter', preventDefault() {} });
  };
  const message = () => document.querySelector('#message');
  return {
    submit, saved, replaced, asked, pick, count, filterBy, emptyShown,
    rows, titleOf, startRename, rename, message, confirms, timers,
  };
}

const todo = (id, title, done = false) => ({ id, title, done, createdAt: 1 });

// A file whose text() resolves only when the test says so.
function slowFile(text) {
  let finish;
  const done = new Promise((resolve) => { finish = resolve; });
  return { file: { size: text.length, text: () => done.then(() => text) }, finish };
}

function backupOf(...titles) {
  return backup.toBackupText(titles.map((title, i) => ({ id: `id-${title}-${i}`, title, done: false, createdAt: 1 })));
}

