const path = require('node:path');
const vm = require('node:vm');
const crypto = require('node:crypto');
const backup = require('../app/backup.js');

const appJs = fs.readFileSync(path.join(__dirname, '..', 'app', 'app.js'), 'utf8');

// Setting innerHTML or textContent drops what was appended, as in a real page; `appended` is what is left.
function fakeElement() {
  let html = '';
  let text = '';
  const el = {
    hidden: false, value: '', className: '', dataset: {}, attributes: {}, appended: [],
    get innerHTML() { return html; },
    set innerHTML(v) { html = v; el.appended = []; },
    get textContent() { return text; },
    set textContent(v) { text = v; el.appended = []; },
    append(...nodes) { el.appended.push(...nodes); },
    setAttribute(name, value) { el.attributes[name] = value; },
    replaceWith(node) { el.replacedWith = node; },
    remove() { el.removed = true; },
    focus() {},
    querySelector(sel) { return (el.children[sel] ||= fakeElement()); },
    children: {},
  };
  return el;
}

// Loads app.js on a readable list (empty unless given) and returns the add form plus every list the app tried to save.
// `saveResult` is what store.save answers ('saved', 'failed', or 'skipped' with `readError`).
function loadApp(initial = [], { saveResult = 'saved', readError = false } = {}) {
  const elements = {};
  const saved = [];
  const replaced = [];
  const store = {
    readError,
    load() { return { todos: initial, readError }; },
    save(todos) { saved.push(todos.map((t) => ({ ...t }))); return saveResult; },
    replace(todos) { replaced.push(todos); return 'saved'; },
  };
  const document = {
    querySelector(sel) { return (elements[sel] ||= fakeElement()); },
    querySelectorAll() { return []; },
    createElement() { return fakeElement(); },
  };
  // Native confirm() is recorded and answered "OK"; timers are recorded and fired by the test.
  const confirms = [];
  const timers = [];
  const confirm = (q) => { confirms.push(q); return true; };
  const setTimeout = (fn, ms) => timers.push({ fn, ms });
  const clearTimeout = (id) => { if (timers[id - 1]) timers[id - 1].fn = () => {}; };
  vm.runInNewContext(appJs, { ...backup, store, document, crypto, confirm, setTimeout, clearTimeout });
  const submit = (value) => {
    document.querySelector('#title').value = value;
    document.querySelector('#add').onsubmit({ preventDefault() {} });
  };
  // The confirm dialog records each question and answers "Huỷ".
  const asked = [];
  Object.assign(document.querySelector('#confirm'), {
    showModal() { asked.push(document.querySelector('#confirm-text').textContent); },
    addEventListener(type, fn) { queueMicrotask(fn); },
  });
  const pick = (file) => document.querySelector('#import').onchange({ target: { files: [file], value: '' } });
  const count = () => document.querySelector('#count').textContent;
  // Clicks a filter tab: 'all', 'open' or 'done'.
  const filterBy = (f) => document.querySelector('#filters').onclick({ target: { dataset: { filter: f } } });
  const emptyShown = () => !document.querySelector('#empty').hidden;
  // Rows on screen; renaming opens the edit box on row `row` (double-click, or a key such as 'Enter') and presses Enter.
  const rows = () => document.querySelector('#list').appended;
  const titleOf = (row) => rows()[row].querySelector('span');
  const startRename = (row, key) => {
    const span = titleOf(row);
    if (key) span.onkeydown({ key, preventDefault() {} });
    else span.ondblclick();
    return span.replacedWith;
  };
  const rename = (row, value, key) => {
    const input = startRename(row, key);
    input.value = value;
    input.onkeydown({ key: 'Enter', preventDefault() {} });
  };
  const message = () => document.querySelector('#message');
  return {
    submit, saved, replaced, asked, pick, count, filterBy, emptyShown,
    rows, titleOf, startRename, rename, message, confirms, timers,
  };
}

const todo = (id, title, done = false) => ({ id, title, done, createdAt: 1 });

// A file whose text() resolves only when the test says so.
function slowFile(text) {
  let finish;
  const done = new Promise((resolve) => { finish = resolve; });
  return { file: { size: text.length, text: () => done.then(() => text) }, finish };
}

function backupOf(...titles) {
  return backup.toBackupText(titles.map((title, i) => ({ id: `id-${title}-${i}`, title, done: false, createdAt: 1 })));
}

test('add form: trims the title and makes a string id', () => {
  const { submit, saved } = loadApp();
  submit('  Mua sữa  ');
  assert.equal(saved.length, 1);
  const [t] = saved[0];
  assert.equal(t.title, 'Mua sữa');
  assert.equal(typeof t.id, 'string');
  assert.notEqual(t.id, '');
  assert.equal(t.done, false);
  assert.equal(typeof t.createdAt, 'number');
});

test('add form: skips a whitespace-only title', () => {
  const { submit, saved } = loadApp();
  submit('   ');
  submit('\t\n');
  assert.equal(saved.length, 0);
});

test('open-todo count line: a dot every three digits from 1,000 up, like every other sentence (Linh, R9)', () => {
  const todos = (n, done = false) =>
    Array.from({ length: n }, (_, i) => ({ id: `id-${done}-${i}`, title: `Việc ${i}`, done, createdAt: 1 }));
  const { submit, count } = loadApp([...todos(999), ...todos(5, true)]);
  assert.equal(count(), '999 việc chưa xong');
  submit('Việc thứ 1000');
  assert.equal(count(), '1.000 việc chưa xong');
  assert.equal(loadApp(todos(12)).count(), '12 việc chưa xong');
  assert.equal(loadApp(todos(2001)).count(), '2.001 việc chưa xong');
  assert.equal(loadApp(todos(12500)).count(), '12.500 việc chưa xong');
});

test('open-todo count line counts the whole list, whatever the filter (T-013)', () => {
  const todo = (i, done) => ({ id: `id-${i}`, title: `Việc ${i}`, done, createdAt: 1 });
  const { count, filterBy } = loadApp([todo(1, false), todo(2, false), todo(3, false), todo(4, true), todo(5, true)]);
  assert.equal(count(), '3 việc chưa xong');
  filterBy('done');
  assert.equal(count(), '3 việc chưa xong', 'tab "Đã xong"');
  filterBy('open');
  assert.equal(count(), '3 việc chưa xong', 'tab "Chưa xong"');
  filterBy('all');
  assert.equal(count(), '3 việc chưa xong', 'back to tab "Tất cả"');
});

test('empty-list message only when the whole list is empty, not when a filter hides everything (T-014)', () => {
  const todo = (i, done) => ({ id: `id-${i}`, title: `Việc ${i}`, done, createdAt: 1 });
  const { emptyShown, filterBy } = loadApp([todo(1, false), todo(2, false), todo(3, false), todo(4, false)]);
  assert.equal(emptyShown(), false);
  filterBy('done');
  assert.equal(emptyShown(), false, 'tab "Đã xong" with no done todos');
  const allDone = loadApp([todo(1, true)]);
  allDone.filterBy('open');
  assert.equal(allDone.emptyShown(), false, 'tab "Chưa xong" with no open todos');
  assert.equal(loadApp([]).emptyShown(), true, 'a really empty list still shows it');
});

test('a backup of todos the app made imports again', () => {
  const { submit, saved } = loadApp();
  for (const v of ['Mua sữa', '  Gọi mẹ ', '   ', 'Nộp thuế']) submit(v);
  const todos = saved.at(-1);
  assert.equal(todos.length, 3);
  const parsed = backup.parseBackup(backup.toBackupText(todos));
  assert.equal(parsed.ok, true, parsed.message);
  assert.deepEqual(parsed.todos, todos);
});

test('two overlapping imports: the later-finishing one asks before replacing the list the first one filled', async () => {
  const { replaced, asked, pick } = loadApp();
  const large = slowFile(backupOf('Lớn 1', 'Lớn 2', 'Lớn 3'));
  const small = slowFile(backupOf('Nhỏ'));
  const first = pick(large.file);
  const second = pick(small.file);
  small.finish();
  await second;
  assert.equal(replaced.length, 1, 'the small file fills the empty list without asking');
  assert.deepEqual(asked, []);
  large.finish();
  await first;
  assert.deepEqual(asked, [backup.fill(backup.MESSAGES.confirmReplace, { n: 1, m: 3 })]);
  assert.equal(replaced.length, 1, 'cancelled, so the list from the small file stays');
});

test('rename with a filter on renames the todo the user edited, not the one at that place in the whole list (PR 2)', () => {
  const app = loadApp([todo('a', 'Việc A', true), todo('b', 'Việc B')]);
  app.filterBy('open');
  app.rename(0, 'Việc B mới');
  assert.deepEqual(app.saved.at(-1).map((t) => t.title), ['Việc A', 'Việc B mới']);
});

test('the rename message shows the new title as text, never as HTML (policy-security#S3, PR 2)', () => {
  const app = loadApp([todo('a', 'Việc A')]);
  const evil = '<img src=x onerror=alert(1)>';
  app.rename(0, evil);
  assert.equal(app.message().innerHTML, '', 'innerHTML never set');
  assert.match(app.message().textContent, /<img src=x onerror=alert\(1\)>/);
});

test('a rename that was not saved never says it worked (policy-ux#U1, PR 2)', () => {
  const failed = loadApp([todo('a', 'Việc A')], { saveResult: 'failed' });
  failed.rename(0, 'Việc A mới');
  assert.equal(failed.message().textContent, backup.MESSAGES.notSaved);
  // After a read error save() answers 'skipped' and the banner already explains it: no "Đã đổi tên" on top.
  const skipped = loadApp([todo('a', 'Việc A')], { saveResult: 'skipped', readError: true });
  skipped.rename(0, 'Việc A mới');
  assert.doesNotMatch(skipped.message().textContent, /Đã đổi tên/);
});

test('rename happens at once, no confirm dialog, with Undo for 10 seconds (policy-ux#U2, PR 2)', () => {
  const app = loadApp([todo('a', 'Việc A'), todo('b', 'Việc B')]);
  app.rename(1, 'Việc B mới');
  assert.deepEqual(app.confirms, [], 'no confirm dialog');
  assert.deepEqual(app.saved.at(-1).map((t) => t.title), ['Việc A', 'Việc B mới']);
  const undoButton = (a) => a.message().appended.find((node) => typeof node === 'object');
  const undo = undoButton(app);
  assert.equal(undo?.textContent, 'Hoàn tác', 'an Undo button next to the message');
  assert.deepEqual(app.timers.map((t) => t.ms), [10000]);
  undo.onclick();
  assert.deepEqual(app.saved.at(-1).map((t) => t.title), ['Việc A', 'Việc B'], 'Undo puts the old title back, saved');

  const later = loadApp([todo('a', 'Việc A')]);
  later.rename(0, 'Việc A mới');
  const button = undoButton(later);
  later.timers[0].fn();
  assert.equal(button.removed, true, 'the Undo button goes after 10 seconds');
});

test('renaming starts from the keyboard: the title takes focus, Enter or F2 opens the edit box (policy-ux#U5, PR 2)', () => {
  const app = loadApp([todo('a', 'Việc A'), todo('b', 'Việc B')]);
  assert.equal(app.titleOf(0).tabIndex, 0, 'the title can get keyboard focus');
  assert.equal(typeof app.titleOf(0).onkeydown, 'function', 'the title listens to keys');
  app.rename(0, 'Việc A mới', 'Enter');
  app.rename(1, 'Việc B mới', 'F2');
  assert.deepEqual(app.saved.at(-1).map((t) => t.title), ['Việc A mới', 'Việc B mới']);
  assert.equal(app.startRename(0, 'a'), undefined, 'other keys do nothing');
});

// The title sits in the checkbox's <label>, so a page would turn every click on it into a click on the checkbox. The fake page
// has no labels; what it can pin is that the title cancels its own clicks, so a double-click to rename never ticks the todo.
test('clicking or double-clicking the title never ticks the todo (PR 2, review watch-1)', () => {
  const app = loadApp([todo('a', 'Việc A')]);
  const span = app.titleOf(0);
  let cancelled = 0;
  for (let i = 0; i < 2; i++) span.onclick?.({ preventDefault() { cancelled++; } });
  assert.equal(cancelled, 2, 'both clicks of a double-click are kept from reaching the checkbox');
});

test('Enter while an input method is composing (Vietnamese Telex) does not save a half-typed name (PR 2)', () => {
  const app = loadApp([todo('a', 'Việc A')]);
  const input = app.startRename(0);
  input.value = 'Việc A m';
  input.onkeydown({ key: 'Enter', isComposing: true, preventDefault() {} });
  assert.equal(app.saved.length, 0);
});

